package com.yeyamo_mobile.api.recommendation_service.application;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import com.yeyamo_mobile.api.recommendation_service.application.port.*;import com.yeyamo_mobile.api.recommendation_service.application.scoring.*;import com.yeyamo_mobile.api.recommendation_service.domain.*;
class RecommendationQueryServiceTest{@Test void ranksCandidatesAndWritesOutboxOnCacheMiss(){var projections=mock(RecommendationProjectionPort.class);var cache=mock(RecommendationCachePort.class);var outbox=mock(RecommendationOutboxPort.class);var context=new RecommendationContext(null,null);when(cache.get("u",context,0,1)).thenReturn(Optional.empty());when(projections.profile("u")).thenReturn(new RecommendationProfile("u",null,false,Map.of(),Set.of()));when(projections.activeCandidates(500)).thenReturn(List.of(candidate("1",1),candidate("2",100)));var service=new RecommendationQueryService(projections,cache,outbox,List.of(new PopularityScoringStrategy()));var page=service.recommend("u",context,0,1,"c1");assertEquals("2",page.items().getFirst().targetId());assertTrue(page.hasNext());verify(cache).put(eq("u"),eq(context),eq(0),eq(1),same(page));verify(outbox).append(eq("recommendation.generated"),eq("u"),eq("c1"),anyMap());}@Test void cacheHitAvoidsProjectionAndOutbox(){var projections=mock(RecommendationProjectionPort.class);var cache=mock(RecommendationCachePort.class);var outbox=mock(RecommendationOutboxPort.class);var context=new RecommendationContext(null,null);var cached=new RecommendationPage(0,20,false,List.of(),Instant.now());when(cache.get("u",context,0,20)).thenReturn(Optional.of(cached));assertSame(cached,new RecommendationQueryService(projections,cache,outbox,List.of()).recommend("u",context,0,20,null));verifyNoInteractions(projections,outbox);}private Candidate candidate(String id,double popularity){return new Candidate("catalog:"+id,id,CandidateKind.PLACE,"P"+id,null,null,null,null,popularity,true,Instant.now(),Instant.now());}}
